GRAMMAR={"title":"can / can’t for abilities and requests","explanation_en":"Use can + base verb for ability. Use can’t for no ability. Can you...? asks about ability or makes a simple request.","explanation_ar":"نستخدم can ثم الفعل الأساسي للقدرة، وcan’t لعدم القدرة، وCan you…? للسؤال أو الطلب البسيط.","examples":("I can swim.","She can’t ride a bike.","Can he cook?","Can you help me, please?"),"common_mistakes":("She can swims → She can swim","I don’t can → I can’t","Can you to help? → Can you help?"),"tips":("الفعل بعد can لا يأخذ s أو to.","أضف please لجعل الطلب ألطف.")}
LISTENING={"dialogue":(("Coach","What can you do, Faisal?"),("Faisal","I can swim and ride a bike, but I can’t cook."),("Coach","Can your sister swim?"),("Faisal","No, she can’t, but she can draw very well."),("Coach","Can you help me carry these bags?"),("Faisal","Yes, of course.")),"audio_text":"I can swim and ride a bike, but I cannot cook. My sister cannot swim, but she can draw. Yes, I can help carry the bags.","transcript":(("Coach","What can you do, Faisal?"),("Faisal","I can swim and ride a bike, but I can’t cook."),("Coach","Can your sister swim?"),("Faisal","No, she can’t, but she can draw very well."),("Coach","Can you help me carry these bags?"),("Faisal","Yes, of course.")),"hide_transcript_until_attempt":True,"questions":(aq("What can Faisal do?",("swim and bike","cook and sing","draw only"),"swim and bike"),aq("Can his sister swim?",("yes","no","not stated"),"no"),aq("What help does the coach need?",("carry bags","open door","use computer"),"carry bags"))}
